mapper.select:
SELECT COUNT(*) FROM orders

    AND status = #{status}
    AND shop_id = #{shopId}

SELECT o.id, o.order_no AS orderNo, o.user_id AS userId, o.shop_id AS shopId, o.total_amount AS totalAmount, o.remark, o.status, o.pay_status AS payStatus, o.rider_id AS riderId, o.pay_time AS payTime, o.finish_time AS finishTime, o.cancel_time AS cancelTime, o.create_time AS createTime, s.shop_name AS shopName, r.real_name AS riderName FROM orders o LEFT JOIN merchant_shop s ON s.id = o.shop_id LEFT JOIN rider r ON r.id = o.rider_id
AND o.status = #{status} AND o.shop_id = #{shopId}
ORDER BY o.id DESC LIMIT #{pageSize} OFFSET #{offset}
